// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2020, "2-3", [{"author":"И. Рубанов","question":"Что не является названием мяса?","choices":["<em>курятина</em>","<em>телятина</em>","<em>свинина</em>","<em>баранина</em>","<em>вкуснятина</em>."],"key":"Д","review":["Названия мяса","Проверь, какое животное стоит за каждым названием. Курятина — мясо курицы, телятина — телёнка, свинина — свиньи, баранина — барана.","«Вкуснятина» может быть любым вкусным угощением, например пирогом или ягодами. Она не обозначает отдельный вид мяса. Ответ Д."]},{"author":"О. Подлесская","question":"Вот начало чешской народной песенки в переводе Самуила Маршака:\n<em>— Кума, ты к нам?</em>\n<em>— К вам, к вам, к вам, к вам!</em>\nКак называется это стихотворение? «Разговор …».","choices":["кукушек","лягушек","индюшек","курочек","уточек."],"key":"Б","review":["Разговор из песенки","Прочитай «к вам, к вам» несколько раз подряд. В каждом повторе слышится «ква».","«Ква-ква» — так передают кваканье лягушек. Значит, Маршак дал песенке название «Разговор лягушек», вариант Б."]},{"author":"И. Рубанов","question":"<em>Суп</em> — <em>варить</em>, <em>котлеты</em> — <em>жарить</em>, <em>пироги</em> — … .","choices":["<em>делать</em>","<em>лепить</em>","<em>начинять</em>","<em>печь</em>","<em>есть</em>."],"key":"Г","review":["Готовим обед","«Суп варят» и «котлеты жарят» — примеры того, как блюда доводят до готовности. Подбери такой же глагол для пирогов.","Сырые пироги ставят в печь или духовку. Особый способ приготовления здесь передаёт глагол «печь», вариант Г."]},{"author":"Б. Иомдин","question":"Какая пара устроена по смыслу не так, как другие?","choices":["<em>внук — внучок</em>","<em>пастух — пастушок</em>","<em>кабан — кабачок</em>","<em>баран — барашек</em>","<em>орех — орешек</em>."],"key":"В","review":["Что означает второе слово","Внучок — ласково о внуке, пастушок — о пастухе. Барашек — молодой баран, орешек — маленький орех.","Ласково кабана можно назвать «кабанчиком». Похожее слово «кабачок» обозначает овощ. По смыслу отличается пара В."]},{"author":"И. Рубанов","question":"Как лучше передать негромкий смех?","choices":["<em>ха-ха-ха</em>","<em>хи-хи-хи</em>","<em>хо-хо-хо</em>","<em>го-го-го</em>","<em>гы-гы-гы</em>."],"key":"Б","review":["Как звучит смешок","Вспомни глагол «хихикать». Он обозначает тихий смех, и его начало похоже на повторяющийся звук.","Этот негромкий смешок записывают как «хи-хи-хи». «Ха-ха-ха» обычно передаёт более открытый смех. Выбираем вариант Б."]},{"author":"И. Иткин","question":"В какой паре слова означают одно и то же?","choices":["<em>уйти — зайти</em>","<em>угадать — загадать</em>","<em>уснуть — заснуть</em>","<em>украсить — закрасить</em>","<em>уговорить — заговорить</em>."],"key":"В","review":["Что меняют приставки","Придумай примеры: уйти из дома и зайти в дом, угадать ответ и загадать загадку, украсить альбом и закрасить пятно, уговорить друга и заговорить первым. В каждой паре действия различаются.","«Малыш уснул» и «малыш заснул» сообщают, что он погрузился в сон. Только эта пара передаёт одно и то же действие — вариант В."]},{"author":"О. Подлесская","question":"— <em>Мама, скорей, котлеты перегорели!</em>\n— <em>Не перегорели, а _________.</em>","choices":["<em>прогорели</em>","<em>подгорели</em>","<em>загорели</em>","<em>угорели</em>","<em>выгорели</em>."],"key":"Б","review":["Котлеты на сковороде","Когда еда слишком долго жарится, на ней может появиться обгоревшая корочка. Про котлеты в таком случае говорят «подгорели».","Глагол «перегорела» подходит, например, для лампочки. Мама исправила фразу на «котлеты подгорели», вариант Б."]},{"author":"Е. Муравенко","question":"В предложении <em>Мет</em><strong><em>ро за</em></strong><em>крыто</em> «спрятано» слово <em>роза</em>. В четырёх из этих пяти предложений «спрятано» то, что можно съесть или выпить на завтрак, а в одном — предмет мебели. В каком?","choices":["<em>Рама сломалась</em>.","<em>Бусы рассыпались</em>.","<em>Малышка шалит</em>.","<em>Кошка фыркает.</em>","<em>Колесо катится</em>."],"key":"Г","review":["Слова на стыке","Читай последние буквы первого слова и первые буквы второго подряд. «Ра[ма сло]малась» даёт «масло», «бу[сы р]ассыпались» — «сыр», «малыш[ка ша]лит» — «каша», «коле[со к]атится» — «сок».","В «ко[шка ф]ыркает» соединяются «шка» и «ф». Получается «шкаф», единственный предмет мебели. Ответ Г."]},{"author":"М. Мирошниченко","question":"Какое слово не связано по смыслу с другими?","choices":["<em>звонок</em>","<em>перезвон</em>","<em>звонкий</em>","<em>зазвонить</em>","<em>позвоночник</em>."],"key":"Д","review":["Похожие буквы, разные слова","Звонок издаёт звон, перезвон состоит из звуков колоколов, звонкий звук хорошо слышен, а зазвонить — начать издавать звон.","У позвоночника похожее сочетание букв, но он состоит из позвонков и относится к строению тела. Лишний вариант Д."]},{"author":"О. Подлесская","question":"Найдите пару слов, которые обозначают одно и то же.","choices":["<em>пол — полка</em>","<em>нож — ножка</em>","<em>рулет — рулетка</em>","<em>кувшин — кувшинка</em>","<em>табурет — табуретка</em>."],"key":"Д","review":["Два названия предмета","Проверь значения слов. Полка отличается от пола, ножка — от ножа, рулетка — от рулета, а кувшинка — водяное растение, тогда как кувшин — сосуд.","Табурет и табуретка — сиденье на ножках без спинки. Одно и то же можно назвать обоими словами из варианта Д."]},{"author":"Л. Фёдорова","question":"В каком примере, скорее всего, Моника сделала ошибку?","choices":["<em>Какие тут вишни!</em>","<em>Какие тут яблоки!</em>","<em>Какие тут малины!</em>","<em>Какие тут сливы!</em>","<em>Сколько тут смородины!</em>"],"key":"В","review":["Ягоды и фрукты","Вишни, яблоки и сливы легко назвать и пересчитать поштучно. Поэтому фразы «Какие тут вишни!» и «Какие тут сливы!» звучат естественно.","Малину, как и смородину, обычно называют в единственном числе, когда говорят о ягодах в целом. Обычная реплика — «Какая тут малина!». Ошибка, скорее всего, в варианте В."]},{"author":"О. Подлесская","question":"В каком отрывке слово <em>вдруг</em> значит не то же, что в остальных?","choices":["Вдруг на них из закоулка пёс большой залаял гулко. (Д. Хармс)","Вдруг из чёрной темноты в небе выросли кусты. (К. Чуковский)","Вдруг забудут, не найдут? — Где ты, Оленька? — Я тут! (З. Александрова)","Вдруг откуда-то летит маленький комарик,\nИ в руке его горит маленький фонарик. (К. Чуковский)","Вдруг откуда-то шакал на кобыле прискакал. (К. Чуковский)"],"key":"В","review":["Два значения слова «вдруг»","В отрывках про пса, кусты, комарика и шакала что-то произошло неожиданно. В них слово «вдруг» можно заменить на «внезапно».","Оленька тревожится, что её могут забыть. Её вопрос «Вдруг забудут?» значит «А что, если забудут?». Это другое значение, вариант В."]},{"author":"Е. Муравенко","question":"Вот строки из стихотворения Самуила Маршака «Зебры»:\nАфриканские лоша__ки,\nХорошо играть вам в пря__ки.\nРазлинованы лоша__ки,\nСловно школьные тетра__ки.\n\nКакие буквы нужно вставить на месте пропусков?","choices":["<em>д</em>, <em>т</em>, <em>д</em>, <em>д</em>","<em>д</em>, <em>т</em>, <em>д</em>, <em>т</em>","<em>т</em>, <em>т</em>, <em>т</em>, <em>д</em>","<em>д</em>, <em>д</em>, <em>д</em>, <em>д</em>","<em>т</em>, <em>т</em>, <em>т</em>, <em>т</em>."],"key":"А","review":["Пропуски в стихах о зебрах","Чтобы услышать сомнительную согласную, поменяй форму слова. «Лошадки» проверяются словом «лошадок», а «тетрадки» — словом «тетрадок». В этих случаях пишется д.","В слове «прятки» слышна та же согласная, что в «прятать». Вставляем по очереди д, т, д, д. Такая последовательность дана в варианте А."]},{"author":"О. Подлесская","question":"Перед вами — детская потешка:\nИвану-большаку — дрова рубить.\nВаське-указке — воду носить.\nМишке-… — печку топить.\nГришке-сиротке — кашку варить.\nКрошке-Тимошке — песенки петь…\n\nКакое слово должно идти после слова Мишке?","choices":["<em>большому</em>","<em>маленькому</em>","<em>среднему</em>","<em>толстому</em>","<em>тонкому</em>."],"key":"В","review":["Братья из потешки","В потешке пять героев. Иван-большак — старший, а крошка Тимошка — самый маленький. Мишка назван третьим, в середине.","Положение героя подсказывает слово «среднему». Получается «Мишке-среднему — печку топить», вариант В."]},{"author":"О. Подлесская","question":"В стихах Самуила Маршака, посвящённых каждому месяцу года и его приметам, читаем про март:\nРыхлый снег темнеет в марте.\nТают льдинки на окне.\n______ бегает по парте\nИ по карте на стене.\n\nКакое слово мы пропустили?","choices":["<em>мышка</em>","<em>кошка</em>","<em>белка</em>","<em>зайчик</em>","<em>птичка</em>."],"key":"Г","review":["Март у окна","В марте снег тает, и на парту и стену падает свет из окна. Отражение солнечного света может перемещаться по комнате.","Такое светлое пятнышко называют солнечным зайчиком. Поэтому по парте и карте «бегает» зайчик, вариант Г."]},{"author":"Б. Иомдин","question":"На что начинаются многие русские слова?","choices":["<em>аа</em>","<em>бб</em>","<em>вв</em>","<em>гг</em>","<em>дд</em>."],"key":"В","review":["Двойное начало слова","Посмотри, какие буквы встречаются на стыке приставки и корня. В слове «ввести» приставка в- стоит перед начальной в слова «вести».","Ещё примеры — «ввозить», «вверху» и «ввысь». Две буквы в действительно часто встречаются в начале слов. Это вариант В."]},{"author":"С. Сай","question":"У Кати очень хороший и аккуратный почерк, но вот это слово в её тетрадке прочитать очень трудно.","choices":["<em>заберёте</em>","<em>лишили</em>","<em>обобрал</em>","<em>отнимут</em>","<em>выкрадывает</em>."],"key":"Б","review":["Слово в тетради Кати","Представь, как слова выглядят, если их написать быстро и связно. У строчных л, и и ш в рукописном начертании похожие короткие штрихи и соединения.","Слово «лишили» целиком состоит из этих букв, поэтому глаз легко путает границы между ними. Труднее всего прочитать вариант Б."]},{"author":"Д. Швайгер и Н. Швайгер","question":"Найдите в ответах подходящий предмет для каждого действия: <em>разбиться</em>, <em>порваться</em>, <em>перегореть</em>, <em>сесть</em>. Какой предмет оказался лишним?","choices":["лампочка","зеркало","карандаш","батарейка","рубашка."],"key":"В","review":["Что может случиться","Зеркало разбивается, рубашка рвётся, лампочка перегорает, а батарейка садится. Каждому действию соответствует свой предмет.","Для карандаша обычно говорят «сломался» или «затупился». Он остался без пары, вариант В."]},{"author":"Е. Муравенко","question":"Из всех написанных ниже слов, кроме одного, можно вычеркнуть один слог (в начале, середине или конце слова) и получить новое слово. Из какого слова таким способом новое слово не получится?","choices":["<em>полено</em>","<em>пароход</em>","<em>король</em>","<em>ширина</em>","<em>жеребёнок</em>."],"key":"Б","review":["Один слог долой","Из «полено» убери «но» и получишь «поле». Из «король» вычеркни «ко» и останется «роль». Из «ширина» без «ри» получается «шина», а из «жеребёнок» без «же» — «ребёнок».","У «парохода» можно вычеркнуть «па», «ро» или «ход». Остатки «роход», «паход» и «паро» самостоятельными общеупотребительными словами не являются. Ответ Б."]},{"author":"Е. Муравенко","question":"Во всех двустишиях последние слова нужно заменить другими: в четырёх двустишиях — «зимними», а в одном — «летним». В каком нужно «летнее» слово?","choices":["На рисунке у Маринки\nС неба падают пружинки.","Ну-ка, берегись, дружок,\nКину я в тебя кружок.","Марк не слышал слова «стоп» —\nПровалился он в сироп.","Теплоход уж не пройдёт:\nПревратилась речка в мёд.","В речке плавать нам пора,\nВедь на улице дыра!"],"key":"Д","review":["Зима и лето в двустишиях","Восстанови рифмы и смысл. С неба падают снежинки, в дружка кидают снежок, Марк провалился в сугроб, а теплоходу мешает лёд.","Купаться в речке хочется, когда на улице жара. «Жара» рифмуется со словом «пора» и подходит к лету. Это двустишие Д."]},{"author":"И. Иткин","question":"В сказке Александра Шарова «Человек-горошина и Простак» есть персонаж по имени Ахум. Этот персонаж … .","choices":["умеет летать и очень любит варенье","всего боится и очень быстро бегает","рыжий и очень хитрый","очень большой и плавает в море","знает все языки."],"key":"А","review":["Сказочный Ахум","Попробуй прочитать имя «Ахум» с конца. Получится «муха», и это подсказка к тому, кто скрывается под сказочным именем.","Муха умеет летать и слетается на сладкое варенье. Ахум у Шарова — летающая муха, которую угощают вареньем. Ответ А."]},{"author":"Л. Фёдорова","question":"Какое имя сказочного персонажа из книг Туве Янссон содержит самый длинный слог (по числу звуков)?","choices":["<em>Муми-тролль</em>","<em>Снусмумрик</em>","<em>Хемуль</em>","<em>Снорк</em>","<em>Филифьонка</em>."],"key":"Г","review":["Длинный слог в имени","Считай звуки в одном слоге, а не буквы во всём имени. Например, «тролль» даёт четыре звука [т], [р], [о], [л’]. Две л и мягкий знак передают здесь один мягкий звук.","В имени «Снорк» только одна гласная, поэтому все пять звуков [с], [н], [о], [р], [к] входят в один слог. У остальных имён слоги короче. Ответ Г."]},{"author":"Б. Иомдин","question":"Слова کوکو (на языке фарси́) и קוקו (на языке и́диш) означают … .","choices":["‘бабочка’","‘кукушка’","‘щука’","‘лиса’","‘слон’."],"key":"Б","review":["Два слова на разных языках","В обеих записях одни и те же знаки повторяются парами. Слова звучат примерно как «ку-ку» — это два одинаковых слога.","В русском языке «ку-ку» передаёт крик кукушки. Повторяющийся слог даёт ключ к названию птицы, вариант Б."]},{"author":"Е. Бикмаев","question":"Дима написал на полоске бумаги слово <em>колесо</em> и склеил её концами в кольцо. Шов склейки он сделал маленьким, так что крайние буквы стали как соседние. По его правилам, на кольце нужно искать слова, двигаясь от буквы к букве в любом направлении.\n\nк о л е с о\n\nКакое слово нельзя найти на этом кольце?","choices":["<em>село</em>","<em>лесок</em>","<em>сокол</em>","<em>колос</em>","<em>окосел</em>."],"key":"Г","review":["Буквы на кольце","После склейки порядок идёт по кругу к–о–л–е–с–о–к. «Село» и «окосел» читаются в обратном направлении, а «лесок» и «сокол» — в прямом.","Для «колос» от к нужно идти к о, за которым следует л. После этой л по ходу стоит е, а в другую сторону от к буквы л после о вообще нет. «Колос» прочитать нельзя, ответ Г."]},{"author":"О. Подлесская","question":"В стихотворении молдавского поэта Григоре Виеру в переводе Якова Акима мы пропустили некоторые слова.\nСколько слов в пропущенных строчках?\n\n(...)\nДождь считает пузыри.\n(...)\nНа дороге луж не счесть.\n(...)\nДождик, что с тобою делать?","choices":["3","6","9","12","15."],"key":"В","review":["Дождик и пузыри","В строках дождик считает пузыри и лужи. Рифмы «пузыри» и «не счесть» подсказывают окончания двух цепочек счёта — «три» и «шесть».","В считалке пропущены «раз, два, три», «четыре, пять, шесть» и «семь, восемь, девять». В каждой строке три слова, всего девять. Ответ В."]},{"author":"С. Дьяченко","question":"Двух маленьких сестёр зовут <em>Мира</em> и <em>Ирма</em>. Сколько в их именах одинаковых звуков?","choices":["4","3","2","1","0."],"key":"Б","review":["Имена двух сестёр","Произнеси «Мира» и «Ирма». В первом имени м перед и мягкое, а во втором м перед а твёрдое.","Совпадают гласный под ударением, конечный безударный гласный и твёрдый [р]. Получается три совпадающих звука, вариант Б."]},{"author":"О. Подлесская","question":"В повести Владислава Крапивина «Лётчик для особых поручений» четверо друзей играли на громадном пустыре. Это место они называли как одну из частей света. Они вырезали на столбе ножиком свои имена:\n\nАНТОН\nАРКАШКА\nТИМА\n…\n\nКак звали четвёртого мальчика?","choices":["Алёшка","Олежек","Данилка","Лёнька","Ромка."],"key":"В","review":["Имена на столбе","Пустырь назывался как часть света. Возьми начала имён «Антон», «Аркашка» и «Тима» так, чтобы получилось начало слова АНТ–АРК–ТИ.","До полной «Антарктиды» остаётся ДА. Из перечисленных имён с ДА начинается только Данилка. Это вариант В."]},{"author":"О. Подлесская","question":"Четыре загадки описывают один и тот же предмет, а пятая <em>—</em> другой. Найдите ответ на эту «лишнюю» загадку. (1) <em>Птичка-невеличка: носик стальной, а хвостик льняной</em>. (2) <em>Скручена, связана, на кол посажена, а по двору пляшет</em>. (3) <em>Рогатая, хвостатая, рогом проткнёт, хвостом починит</em>. (4) <em>Железная рыбка ныряет, а хвост на волне оставляет</em>. (5) <em>Тонконогая Ненила всех одела-нарядила. На самой бедняжке даже нет</em> <em>рубашки.</em>","choices":["<em>игла</em>","<em>пила</em>","<em>метла</em>","<em>свечка</em>","<em>расчёска</em>."],"key":"В","review":["Пять загадок о предметах","Стальной носик или рог прокалывает ткань, а льняной хвостик тянется за ним. Железная рыбка и Ненила, которая всех одела, тоже описывают иголку с ниткой.","Во второй загадке пучок прутьев привязан к длинной палке и «пляшет» по двору, когда им метут. Она описывает метлу, вариант В."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
